import React from 'react';
import { Plus, MessageSquare, X, ChevronLeft } from 'lucide-react';

const Sidebar = ({ 
  conversations, 
  currentConversation, 
  onNewConversation, 
  onSelectConversation, 
  onDeleteConversation,
  collapsed,
  onToggleCollapse,
  width = 260,
  onResize
}) => {
  const formatDate = (dateString) => {
    if (!dateString) return 'Now';
    
    const date = new Date(dateString);
    const now = new Date();
    
    // Check if it's the same day
    const isToday = date.toDateString() === now.toDateString();
    if (isToday) {
      return 'Today';
    }
    
    // Check if it's yesterday
    const yesterday = new Date(now);
    yesterday.setDate(yesterday.getDate() - 1);
    const isYesterday = date.toDateString() === yesterday.toDateString();
    if (isYesterday) {
      return 'Yesterday';
    }
    
    // Calculate days difference for older dates
    const diffTime = now - date;
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
    
    if (diffDays <= 7) {
      return `${diffDays} days ago`;
    } else {
      return date.toLocaleDateString();
    }
  };

  const truncateText = (text, maxLength = 50) => {
    if (text.length <= maxLength) return text;
    return text.substring(0, maxLength) + '...';
  };

  const handleMouseDown = (e) => {
    if (collapsed) return;
    const startX = e.clientX;
    const startWidth = typeof width === 'number' ? width : 260;
    const minWidth = 180;
    const maxWidth = 480;

    const onMouseMove = (event) => {
      const dx = event.clientX - startX;
      let newWidth = startWidth + dx;
      newWidth = Math.max(minWidth, Math.min(maxWidth, newWidth));
      if (typeof onResize === 'function') {
        onResize(newWidth);
      }
    };

    const onMouseUp = () => {
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mouseup', onMouseUp);
    };

    window.addEventListener('mousemove', onMouseMove);
    window.addEventListener('mouseup', onMouseUp);
  };

  return (
    <div className={`sidebar ${collapsed ? 'collapsed' : ''}`} style={{ width: collapsed ? 0 : width }}>
      <div className="sidebar-top-space">
        <img src="/logo.png" alt="Logo" className="sidebar-logo" />
        <button 
          className="sidebar-hide-btn" 
          onClick={onToggleCollapse}
          title="Hide sidebar"
        >
          <ChevronLeft size={18} />
        </button>
      </div>
      <div className="sidebar-header">
        <button className="new-chat-btn" onClick={onNewConversation}>
          <Plus size={16} />
          New Chat
        </button>
      </div>
      
      <div className="conversations-list">
        {conversations.length === 0 ? (
          <div style={{ 
            padding: '20px', 
            textAlign: 'center', 
            color: '#9ca3af', 
            fontSize: '14px' 
          }}>
            No conversations yet
          </div>
        ) : (
          conversations.map((conversation) => (
            <div
              key={conversation.session_id}
              className={`conversation-item ${
                currentConversation?.session_id === conversation.session_id ? 'active' : ''
              }`}
            >
              <div 
                className="conversation-content"
                onClick={() => onSelectConversation(conversation)}
              >
                <div className="conversation-title">
                  <MessageSquare size={14} style={{ display: 'inline', marginRight: '8px' }} />
                  {conversation.isTemporary 
                    ? "New Chat" 
                    : conversation.isLoading 
                      ? (conversation.original_question ? truncateText(conversation.original_question) : "Processing...")
                      : truncateText(conversation.question_summary || conversation.original_question || "Untitled")
                  }
                </div>
                <div className="conversation-date">
                  {conversation.isTemporary ? "Now" : formatDate(conversation.created_at)}
                </div>
              </div>
              <button
                className="delete-conversation-btn"
                onClick={(e) => {
                  e.stopPropagation();
                  onDeleteConversation(conversation.session_id);
                }}
                title={conversation.isTemporary ? "Close chat" : "Delete conversation"}
              >
                <X size={14} />
              </button>
            </div>
          ))
        )}
      </div>
      {!collapsed && (
        <div
          className="sidebar-resizer"
          onMouseDown={handleMouseDown}
          title="Drag to resize"
        />
      )}
    </div>
  );
};

export default Sidebar;