import React, { useState, useRef, useEffect } from 'react';
import { Send, Menu, User, Bot, Zap, FileText, BarChart3, Image, Table2, Presentation, Copy } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import ChartRenderer from './ChartRenderer';
import { exportSingleResponseToPdf, exportToPpt, generatePpt, API_BASE_URL } from '../services/api';
import TypingEffect from './TypingEffect';
import ThinkingAnimation from './ThinkingAnimation';

const ChatInterface = ({ 
  conversation, 
  onSendMessage, 
  loading, 
  sidebarCollapsed,
  narrowSidebarVisible = false
}) => {
  const [message, setMessage] = useState('');
  const [messages, setMessages] = useState([]);
  const [selectedOption, setSelectedOption] = useState('Auto');
  const [showSubButtons, setShowSubButtons] = useState(false);
  const [selectedSubOption, setSelectedSubOption] = useState('');
  
  // Scroll detection state
  const [isUserScrolling, setIsUserScrolling] = useState(false);
  const [isNearBottom, setIsNearBottom] = useState(true);

  const messagesEndRef = useRef(null);
  const textareaRef = useRef(null);
  const chatContainerRef = useRef(null);
  const scrollTimeoutRef = useRef(null);

  // Function to extract original question from enhanced message
  const extractOriginalQuestion = (enhancedMessage) => {
    // Check if message contains DataReports template enhancement
    // All DataReports templates follow the pattern: {enhancement}\n\nUser Question: {original_question}
    const dataReportsPattern = /^.*?\n\nUser Question:\s*(.*)/s;
    const match = enhancedMessage.match(dataReportsPattern);
    
    if (match) {
      return match[1].trim();
    }
    
    // If no template pattern found, return the original message
    return enhancedMessage;
  };

  // Option buttons configuration
  const optionButtons = [
    { id: 'Auto', label: 'Flash', icon: Zap },
    { id: 'DataReports', label: 'Data Reports', icon: FileText },
    { id: 'Charts', label: 'Charts', icon: BarChart3 },
    { id: 'Graphics', label: 'Graphics', icon: Image },
    { id: 'Excel', label: 'Excel', icon: Table2 },
    { id: 'PPT', label: 'PPT', icon: Presentation }
  ];

  // Sub-buttons for Data Reports
  const dataReportsSubButtons = [
    { id: 'SalesMarketing', label: 'Sales & Marketing' },
    { id: 'ProductPerformance', label: 'Product Performance' },
    { id: 'CustomerAnalysis', label: 'Customer Analysis' },
    { id: 'HR', label: 'HR' },
    { id: 'Finance', label: 'Finance' }
  ];

  // Sub-buttons for Charts
  const chartsSubButtons = [
    { id: 'Line', label: 'Line' },
    { id: 'Bar', label: 'Bar' },
    { id: 'Pie', label: 'Pie' },
    { id: 'Area', label: 'Area' },
    { id: 'Point', label: 'Point' },
    { id: 'Curve', label: 'Curve' }
  ];

  // Sub-buttons for Excel
  const excelSubButtons = [
    { id: 'Sales', label: 'Sales' },
    { id: 'Finance', label: 'Finance' },
    { id: 'Customer', label: 'Customer' },
    { id: 'Inventory', label: 'Inventory' },
    { id: 'HR', label: 'HR' }
  ];

  // Sub-buttons for PPT
  const pptSubButtons = [
    { id: 'ProductsServices', label: 'Products & Services' },
    { id: 'MarketClients', label: 'Market & Clients' },
    { id: 'PerformanceGrowth', label: 'Performance & Growth' },
    { id: 'StrategyVision', label: 'Strategy & Vision' },
    { id: 'Proposal', label: 'Proposal' }
  ];

  useEffect(() => {
    if (conversation) {
      const formattedMessages = [];
      
      // Only add messages if this is not a temporary conversation
      if (!conversation.isTemporary && conversation.original_question) {
        // Add main question and response
        // Check if this is DataReports mode and extract original question
        let displayQuestion = conversation.original_question;
        if (conversation.selected_option === 'DataReports') {
          displayQuestion = extractOriginalQuestion(conversation.original_question);
        }
        
        formattedMessages.push({
          type: 'user',
          content: displayQuestion,
          timestamp: conversation.created_at
        });
        
        // Only add assistant response if it exists (not loading)
        if (conversation.original_analysis || !conversation.isLoading) {
          formattedMessages.push({
            type: 'assistant',
            content: conversation.original_analysis,
            sql: conversation.original_sql,
            data: conversation.original_data,
            columns: conversation.original_columns,
            timestamp: conversation.created_at,
            isLoading: conversation.isLoading && !conversation.original_analysis,
            selected_option: conversation.selected_option,
            thinkingTime: conversation.thinkingTime,
            doc_file_url: conversation.doc_file_url,
            doc_filename: conversation.doc_filename,
            auto_doc_generated: conversation.auto_doc_generated,
            // Excel-related fields
            excel_file_url: conversation.excel_file_url,
            excel_filename: conversation.excel_filename,
            auto_excel_generated: conversation.auto_excel_generated,
            // Chart-related fields
            has_chart: conversation.has_chart,
            chart_spec: conversation.chart_spec,
            chart_data: conversation.chart_data,
            chart_type: conversation.chart_type,
            chart_error: conversation.chart_error
          });
        } else if (conversation.isLoading) {
          // Add loading message for new conversations
          formattedMessages.push({
            type: 'assistant',
            content: null,
            timestamp: conversation.created_at,
            isLoading: true
          });
        }
      }
      
      // Add followup conversations
      if (conversation.conversation_history) {
        conversation.conversation_history.forEach(item => {
          if (item.type === 'followup') {
            // Check if this is DataReports mode and extract original question for followup too
            let displayFollowupQuestion = item.question;
            if (item.selected_option === 'DataReports') {
              displayFollowupQuestion = extractOriginalQuestion(item.question);
            }
            
            formattedMessages.push({
              type: 'user',
              content: displayFollowupQuestion,
              timestamp: item.timestamp
            });
            
            // Only add assistant response if it exists or show loading
            if (item.analysis || !item.isLoading) {
              formattedMessages.push({
                type: 'assistant',
                content: item.analysis,
                sql: item.sql_query,
                data: item.query_result,
                columns: item.columns,
                timestamp: item.timestamp,
                isLoading: item.isLoading && !item.analysis,
                selected_option: item.selected_option,
                thinkingTime: item.thinkingTime,
                doc_file_url: item.doc_file_url,
                doc_filename: item.doc_filename,
                auto_doc_generated: item.auto_doc_generated,
            // Excel-related fields
            excel_file_url: item.excel_file_url,
            excel_filename: item.excel_filename,
            auto_excel_generated: item.auto_excel_generated,
            // Chart-related fields
            has_chart: item.has_chart,
            chart_spec: item.chart_spec,
            chart_data: item.chart_data,
            chart_type: item.chart_type,
            chart_error: item.chart_error
          });
            } else if (item.isLoading) {
              formattedMessages.push({
                type: 'assistant',
                content: null,
                timestamp: item.timestamp,
                isLoading: true
              });
            }
          }
        });
      }
      
      // Add error message if there's an error
      if (conversation.isError) {
        formattedMessages.push({
          type: 'assistant',
          content: conversation.errorMessage || 'An error occurred. Please try again.',
          timestamp: new Date().toISOString(),
          isError: true
        });
      }
      
      const augmentedMessages = formattedMessages.map((msg) => {
        if (msg.type === 'assistant' && msg.content) {
          // Extract DOC link if not already present
          if (!msg.doc_file_url || !msg.doc_filename) {
            const info = extractDocLinkFromContent(msg.content);
            if (info) {
              msg = {
                ...msg,
                doc_file_url: info.url,
                doc_filename: info.filename,
                auto_doc_generated: msg.auto_doc_generated ?? true,
              };
            }
          }

          // Extract Excel link if not already present
          if (!msg.excel_file_url || !msg.excel_filename) {
            const excelInfo = extractExcelLinkFromContent(msg.content);
            if (excelInfo) {
              msg = {
                ...msg,
                excel_file_url: excelInfo.url,
                excel_filename: excelInfo.filename,
                auto_excel_generated: msg.auto_excel_generated ?? true,
              };
            }
          }
        }
        return msg;
      });
      setMessages(augmentedMessages);
    } else {
      setMessages([]);
    }
  }, [conversation]);

  // Scroll detection and management
  useEffect(() => {
    const chatContainer = chatContainerRef.current;
    if (!chatContainer) return;

    const handleScroll = () => {
      const { scrollTop, scrollHeight, clientHeight } = chatContainer;
      const isAtBottom = scrollHeight - scrollTop - clientHeight < 50; // 50px threshold
      
      setIsNearBottom(isAtBottom);
      
      // Clear existing timeout
      if (scrollTimeoutRef.current) {
        clearTimeout(scrollTimeoutRef.current);
      }
      
      // Set user scrolling flag
      setIsUserScrolling(true);
      
      // Reset user scrolling flag after 1 second of no scrolling
      scrollTimeoutRef.current = setTimeout(() => {
        setIsUserScrolling(false);
      }, 1000);
    };

    chatContainer.addEventListener('scroll', handleScroll);
    
    return () => {
      chatContainer.removeEventListener('scroll', handleScroll);
      if (scrollTimeoutRef.current) {
        clearTimeout(scrollTimeoutRef.current);
      }
    };
  }, []);

  // Auto-scroll logic with user scroll detection
  useEffect(() => {
    // Only auto-scroll if user is not actively scrolling and is near bottom
    if (!isUserScrolling && isNearBottom) {
      scrollToBottom();
    }
  }, [messages, isUserScrolling, isNearBottom]);





  // Enhanced table components for ReactMarkdown
  const tableComponents = {
    table: ({ node, ...props }) => (
      <div className="enhanced-table-wrapper">
        <table className="enhanced-table" {...props} />
      </div>
    ),
    thead: ({ node, ...props }) => (
      <thead className="enhanced-table-header" {...props} />
    ),
    tbody: ({ node, ...props }) => (
      <tbody className="enhanced-table-body" {...props} />
    ),
    tr: ({ node, ...props }) => (
      <tr className="enhanced-table-row" {...props} />
    ),
    th: ({ node, ...props }) => (
      <th className="enhanced-table-header-cell" {...props} />
    ),
    td: ({ node, ...props }) => (
      <td className="enhanced-table-cell" {...props} />
    ),
    code: ({ node, inline, className, children, ...props }) => (
      <code className={className} {...props}>{children}</code>
    ),
    a: ({ node, href, children, ...props }) => {
      // Handle backend export download links with Save As logic (DOCX/XLSX/PPT)
      if (href && href.includes('/api/download/')) {
        const suggestedName = href.split('/api/download/')[1] || 'download';
        const resolvedHref = resolveDownloadUrl(href);
        return (
          <a 
            href={resolvedHref} 
            {...props}
            className="download-link"
            onClick={(e) => {
              e.preventDefault();
              const lower = suggestedName.toLowerCase();
              if (lower.endsWith('.docx')) {
                handleDocDownload(resolvedHref, suggestedName);
              } else if (lower.endsWith('.xlsx')) {
                handleExcelDownload(resolvedHref, suggestedName);
              } else if (lower.endsWith('.pptx')) {
                handlePptDownload(resolvedHref, suggestedName);
              } else {
                // Default to document download for unknown extension
                handleDocDownload(resolvedHref, suggestedName);
              }
            }}
          >
            {children}
          </a>
        );
      }
      
      // Regular links
      return (
        <a href={href} {...props} target="_blank" rel="noopener noreferrer">
          {children}
        </a>
      );
    }
  };

  // Render message text with markdown (CSV rendering removed)
  const renderMessageTextAndTables = (msg, index) => {
    const isLatestAssistant = index === messages.length - 1 && msg.type === 'assistant' && !msg.isLoading && !msg.isError;
    const content = msg.content || '';

    if (isLatestAssistant) {
      if (conversation && conversation.isStreaming === true) {
        return (
          <TypingEffect
            text={content}
            speed={18}
            appendMode={true}
            onProgress={() => {
              // Smart scrolling is now handled by useEffect hooks
              // No forced scrolling during typing to allow user control
            }}
            componentsOverride={tableComponents}
          />
        );
      }
      // Not streaming: render static markdown to avoid re-typing
      return (
        <ReactMarkdown components={tableComponents}>
          {content}
        </ReactMarkdown>
      );
    }

    // Non-latest or non-assistant messages: render as static markdown
    return (
      <ReactMarkdown components={tableComponents}>
        {content}
      </ReactMarkdown>
    );
  };

  // Inline rendering function (CSV rendering removed)
  const renderInlineContent = (content) => {
    return (
      <ReactMarkdown components={tableComponents}>
        {content}
      </ReactMarkdown>
    );
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!message.trim() || loading) return;

    const userMessage = message.trim();
    
    // Create enhanced message with selected option and sub-option
    let enhancedMessage = userMessage;
    
    if (selectedOption === 'Auto') {
      // Treat Auto as Flash mode for fast, brief responses
      enhancedMessage = `[Flash] ${userMessage}`;
    } else {
      if ((selectedOption === 'DataReports' || selectedOption === 'Charts' || selectedOption === 'Excel' || selectedOption === 'PPT') && selectedSubOption) {
        enhancedMessage = `[${selectedOption} - ${selectedSubOption}] ${userMessage}`;
      } else {
        enhancedMessage = `[${selectedOption}] ${userMessage}`;
      }
    }
    
    setMessage('');

    try {
      const isFollowup = conversation !== null;
      await onSendMessage(enhancedMessage, isFollowup);
      
      // The parent component will handle updating the conversation
      // which will trigger a re-render with the new messages
    } catch (error) {
      console.error('Failed to send message:', error);
      // Add error message only on error
      const errorMessage = {
        type: 'assistant',
        content: 'Sorry, I encountered an error while processing your request. Please try again.',
        timestamp: new Date().toISOString(),
        isError: true
      };
      setMessages(prev => [...prev, errorMessage]);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit(e);
    }
  };

  const adjustTextareaHeight = () => {
    const textarea = textareaRef.current;
    if (textarea) {
      textarea.style.height = 'auto';
      textarea.style.height = Math.min(textarea.scrollHeight, 120) + 'px';
    }
  };

  // Extract DOC download link from message content
  const extractDocLinkFromContent = (text) => {
    if (!text) return null;
    // 鎹曡幏docx鏂囦欢
    const rel = text.match(/\/api\/download\/([^\s)"'<>\]]+\.docx)/i);
    if (rel) return { url: rel[0], filename: decodeURIComponent(rel[1]) };
    const abs = text.match(/https?:\/\/[^\s)"'<>]*\/api\/download\/([^\s)"'<>\]]+\.docx)/i);
    if (abs) return { url: abs[0], filename: decodeURIComponent(abs[1]) };
    return null;
  };

  // 浠庢秷鎭唴瀹逛腑鎻愬彇 Excel 涓嬭浇閾炬帴
  const extractExcelLinkFromContent = (text) => {
    if (!text) return null;
    const rel = text.match(/\/api\/download\/([^\s)"'<>\]]+\.xlsx)/i);
    if (rel) return { url: rel[0], filename: decodeURIComponent(rel[1]) };
    const abs = text.match(/https?:\/\/[^\s)"'<>]*\/api\/download\/([^\s)"'<>\]]+\.xlsx)/i);
    if (abs) return { url: abs[0], filename: decodeURIComponent(abs[1]) };
    return null;
  };

  // 浠庢秷鎭唴瀹逛腑鎻愬彇 PPT 涓嬭浇閾炬帴
  const extractPptLinkFromContent = (text) => {
    if (!text) return null;
    const rel = text.match(/\/api\/download\/([^\s)"'<>\]]+\.pptx)/i);
    if (rel) return { url: rel[0], filename: decodeURIComponent(rel[1]) };
    const abs = text.match(/https?:\/\/[^\s)"'<>]*\/api\/download\/([^\s)"'<>\]]+\.pptx)/i);
    if (abs) return { url: abs[0], filename: decodeURIComponent(abs[1]) };
    return null;
  };

  // 鍦ㄦ寕杞芥椂鎭㈠鐢ㄦ埛涓婃鐨勬ā寮忛€夋嫨鍜屽瓙绫诲埆閫夋嫨
  useEffect(() => {
    const savedOption = localStorage.getItem('selectedOption');
    const savedSubOption = localStorage.getItem('selectedSubOption');
    
    if (savedOption) {
      setSelectedOption(savedOption);
      if (savedOption === 'DataReports' || savedOption === 'Charts' || savedOption === 'Excel') {
        setShowSubButtons(true);
        if (savedSubOption) {
          setSelectedSubOption(savedSubOption);
        }
      }
    }
  }, []);

  const handleOptionSelect = (optionId) => {
    setSelectedOption(optionId);
    localStorage.setItem('selectedOption', optionId);
    
    // Toggle sub-buttons for Data Reports, Charts, Excel, and PPT
    if (optionId === 'DataReports' || optionId === 'Charts' || optionId === 'Excel' || optionId === 'PPT') {
      setShowSubButtons(true);
    } else {
      setShowSubButtons(false);
      setSelectedSubOption('');
      localStorage.removeItem('selectedSubOption');
    }
  };

  const handleSubOptionSelect = (subOptionId) => {
    setSelectedSubOption(subOptionId);
    localStorage.setItem('selectedSubOption', subOptionId);
    // Keep sub-buttons visible after selection
  };



  // 娣诲姞锛氱敤浜庘€滃彟瀛樹负鈥濈殑涓嬭浇澶勭悊
  const resolveDownloadUrl = (url) => {
    if (!url) return url;
    const isAbsolute = /^https?:\/\//i.test(url);
    if (isAbsolute) return url;
    const base = API_BASE_URL || (process.env.REACT_APP_API_URL || 'http://localhost:5000');
    if (url.startsWith('/')) return `${base}${url}`;
    return `${base}/${url}`;
  };

  const bustCacheUrl = (url) => {
    try {
      const hasQuery = url.includes('?');
      const sep = hasQuery ? '&' : '?';
      return `${url}${sep}t=${Date.now()}`;
    } catch {
      return url;
    }
  };

  const handleDocDownload = async (url, filename) => {
    try {
      const downloadUrl = bustCacheUrl(resolveDownloadUrl(url));
      const res = await fetch(downloadUrl, { cache: 'no-store', headers: { 'Cache-Control': 'no-cache' } });
      if (!res.ok) throw new Error('涓嬭浇鏂囦欢澶辫触');
      const blob = await res.blob();

      const isInIframe = window.top !== window;
      if (window.showSaveFilePicker && !isInIframe) {
        const handle = await window.showSaveFilePicker({
          suggestedName: filename || 'analysis_report.docx',
          types: [{
            description: 'Word Document',
            accept: { 'application/vnd.openxmlformats-officedocument.wordprocessingml.document': ['.docx'] }
          }]
        });
        const writable = await handle.createWritable();
        await writable.write(blob);
        await writable.close();
      } else {
        const objectUrl = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = objectUrl;
        link.download = filename || 'analysis_report.docx';
        document.body.appendChild(link);
        link.click();
        link.remove();
        URL.revokeObjectURL(objectUrl);
      }
    } catch (err) {
      console.error('DOC 涓嬭浇澶辫触:', err);
      alert('Operation failed, please try again later');
    }
  };
  // Add: handler for Excel file downloads
  const handleExcelDownload = async (url, filename) => {
    try {
      const downloadUrl = bustCacheUrl(resolveDownloadUrl(url));
      const res = await fetch(downloadUrl, { cache: 'no-store', headers: { 'Cache-Control': 'no-cache' } });
      if (!res.ok) throw new Error('涓嬭浇Excel鏂囦欢澶辫触');
      const blob = await res.blob();

      const isInIframe = window.top !== window;
      if (window.showSaveFilePicker && !isInIframe) {
        const handle = await window.showSaveFilePicker({
          suggestedName: filename || 'analysis_report.xlsx',
          types: [{
            description: 'Excel Spreadsheet',
            accept: { 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': ['.xlsx'] }
          }]
        });
        const writable = await handle.createWritable();
        await writable.write(blob);
        await writable.close();
      } else {
        const objectUrl = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = objectUrl;
        link.download = filename || 'analysis_report.xlsx';
        document.body.appendChild(link);
        link.click();
        link.remove();
        URL.revokeObjectURL(objectUrl);
      }
    } catch (err) {
      console.error('Excel 涓嬭浇澶辫触:', err);
      alert('Operation failed, please try again later');
    }
  };

  const handlePdfExport = async (message) => {
    try {
      const sid = conversation?.session_id;
      if (!sid) throw new Error('缂哄皯浼氳瘽ID');
      
      // Extract analysis text from the message
      const analysisText = message?.analysis || message?.content || '';
      if (!analysisText) throw new Error('No analysis content found');
      
      await exportSingleResponseToPdf(sid, analysisText);
    } catch (err) {
      console.error('PDF 瀵煎嚭澶辫触:', err);
      alert('Operation failed, please try again later');
    }
  };

  const handlePptDownload = async (url, filename) => {
    try {
      const downloadUrl = bustCacheUrl(resolveDownloadUrl(url));
      const res = await fetch(downloadUrl, { cache: 'no-store', headers: { 'Cache-Control': 'no-cache' } });
      if (!res.ok) throw new Error('涓嬭浇PPT鏂囦欢澶辫触');
      const blob = await res.blob();

      const isInIframe = window.top !== window;
      if (window.showSaveFilePicker && !isInIframe) {
        const handle = await window.showSaveFilePicker({
          suggestedName: filename || 'presentation.pptx',
          types: [{
            description: 'PowerPoint Presentation',
            accept: { 'application/vnd.openxmlformats-officedocument.presentationml.presentation': ['.pptx'] }
          }]
        });
        const writable = await handle.createWritable();
        await writable.write(blob);
        await writable.close();
      } else {
        const objectUrl = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = objectUrl;
        link.download = filename || 'presentation.pptx';
        document.body.appendChild(link);
        link.click();
        link.remove();
        URL.revokeObjectURL(objectUrl);
      }
    } catch (err) {
      console.error('PPT 涓嬭浇澶辫触:', err);
      alert('Operation failed, please try again later');
    }
  };

  const handlePptExport = async (message) => {
    try {
      const sid = conversation?.session_id;
      if (!sid) throw new Error('缂哄皯浼氳瘽ID');
      
      // Get the selected PPT sub-option type
      const pptType = selectedSubOption || 'Products & Services'; // Default to first type
      
      await exportToPpt(sid, pptType);
    } catch (err) {
      console.error('PPT 瀵煎嚭澶辫触:', err);
      alert('Operation failed, please try again later');
    }
  };

  // Copy message content to clipboard
  const handleCopyMessage = async (messageContent, event) => {
    try {
      // Extract text content from the message, removing markdown formatting
      let textContent = messageContent;
      if (typeof textContent === 'string') {
        // Remove markdown formatting for cleaner copy
        textContent = textContent
          .replace(/\*\*(.*?)\*\*/g, '$1') // Remove bold
          .replace(/\*(.*?)\*/g, '$1') // Remove italic
          .replace(/`(.*?)`/g, '$1') // Remove inline code
          .replace(/```[\s\S]*?```/g, '') // Remove code blocks
          .replace(/#{1,6}\s/g, '') // Remove headers
          .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1') // Remove links, keep text
          .trim();
      }
      
      await navigator.clipboard.writeText(textContent);
      
      // Show a brief success indication (you could also use a toast notification)
      const button = event.target.closest('.copy-button');
      if (button) {
        const originalText = button.innerHTML;
        button.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="20,6 9,17 4,12"></polyline></svg>';
        setTimeout(() => {
          button.innerHTML = originalText;
        }, 1000);
      }
    } catch (err) {
      console.error('Failed to copy message:', err);
      alert('Failed to copy message to clipboard');
    }
  };

  // Render sub-buttons component
  const renderSubButtons = () => {
    if (!showSubButtons) return null;
    
    let subButtons = [];
    if (selectedOption === 'DataReports') {
      subButtons = dataReportsSubButtons;
    } else if (selectedOption === 'Charts') {
      subButtons = chartsSubButtons;
    } else if (selectedOption === 'Excel') {
      subButtons = excelSubButtons;
    } else if (selectedOption === 'PPT') {
      subButtons = pptSubButtons;
    } else {
      return null;
    }
    
    return subButtons.map((subOption) => (
      <button
        key={subOption.id}
        type="button"
        className={`sub-button ${selectedSubOption === subOption.id ? 'active' : ''}`}
        onClick={() => handleSubOptionSelect(subOption.id)}
      >
        {subOption.label}
      </button>
    ));
  };

  // Render option buttons component
  const renderOptionButtons = () => (
    <div className="option-buttons-wrapper">
      <div className="option-buttons-container">
        {optionButtons.map((option) => {
          const IconComponent = option.icon;
          return (
            <button
              key={option.id}
              type="button"
              className={`option-button ${selectedOption === option.id ? 'active' : ''}`}
              onClick={() => handleOptionSelect(option.id)}
            >
              <IconComponent size={16} />
              <span>{option.label}</span>
            </button>
          );
        })}
      </div>
      <div className="sub-buttons-container">
        {renderSubButtons()}
      </div>
    </div>
  );

  return (
    <div className={`chat-interface ${sidebarCollapsed ? 'sidebar-collapsed' : ''} ${narrowSidebarVisible ? 'narrow-sidebar-visible' : ''}`}>
      <div className="chat-header">
        <button className="toggle-sidebar-btn">
          <Menu size={20} />
        </button>
        <h1 className="chat-title">Craveva AI Enterprise Business</h1>
        <div className="powered-by-header">
          Powered by Craveva
        </div>
      </div>

      <div className="chat-messages" ref={chatContainerRef}>
        {messages.length === 0 ? (
          <div className="empty-state">
            <h2>Welcome to Craveva AI Enterprise Business</h2>
            <p>
              Ask questions about your enterprise data and get AI-powered insights. 
              I can help you analyze business metrics, trends, and performance indicators.
            </p>
            
            {/* 灞呬腑鐨勮緭鍏ユ - 鍙湪娌℃湁娑堟伅鏃舵樉绀?*/}
            <div className="centered-input-area">
              <form onSubmit={handleSubmit} className="centered-input-container">
                {/* Option buttons above input */}
                {renderOptionButtons()}
                <div className="centered-input-wrapper">
                  <textarea
                    ref={textareaRef}
                    value={message}
                    onChange={(e) => {
                      setMessage(e.target.value);
                      adjustTextareaHeight();
                    }}
                    onKeyPress={handleKeyPress}
                    placeholder="Ask a question about your enterprise data..."
                    className="centered-message-input"
                    disabled={loading}
                    rows={1}
                  />
                  <button
                    type="submit"
                    className="centered-send-button"
                    disabled={!message.trim() || loading}
                  >
                    <Send size={16} />
                  </button>
                </div>
              </form>
            </div>
          </div>
        ) : (
          <>
            {messages.map((msg, index) => (
              <div key={index} className={`message ${msg.type} ${msg.isError ? 'error' : ''}`}>
                <div className={`message-avatar ${msg.type}`}>
                  {msg.type === 'user' ? <User size={16} /> : <Bot size={16} />}
                </div>
                <div className="message-content">
                  {((!msg.content || (typeof msg.content === 'string' && msg.content.trim() === '')) && (conversation && conversation.isStreaming)) ? (
                    <ThinkingAnimation />
                  ) : (
                    <>
                      {/* Display thinking time for assistant messages */}
                      {msg.type === 'assistant' && msg.thinkingTime && (
                        <div className="thinking-time-display">
                          <span className="thinking-time-text">
                            Thought for {msg.thinkingTime}s
                          </span>
                        </div>
                      )}
                      {renderInlineContent(msg.content)}
                    
                      {/* Display DOC file download button if available */}
                      {msg.doc_file_url && msg.doc_filename && (
                        <div className="doc-download-section">
                          <div className="doc-download-info">
                            <FileText size={16} className="doc-icon" />
                            <span className="doc-text">DOC Report Generated</span>
                          </div>
                          <button 
                            type="button"
                            className="doc-download-button"
                            onClick={() => {
                              handleDocDownload(msg.doc_file_url, msg.doc_filename);
                            }}
                          >
                            Download {msg.doc_filename}
                          </button>
                        </div>
                      )}
                      
                      {/* Display Excel file download button if available */}
                      {msg.excel_file_url && msg.excel_filename && (
                        <div className="excel-download-section">
                          <div className="excel-download-info">
                            <Table2 size={16} className="excel-icon" />
                            <span className="excel-text">Excel Report Generated</span>
                          </div>
                          <button 
                            type="button"
                            className="excel-download-button"
                            onClick={() => {
                              handleExcelDownload(msg.excel_file_url, msg.excel_filename);
                            }}
                          >
                            Download {msg.excel_filename}
                          </button>
                        </div>
                      )}

                      {/* Display PPT file download button if available */}
                      {(() => {
                        const pptLink = extractPptLinkFromContent(msg.content);
                        return pptLink && (
                          <div className="ppt-download-section">
                            <div className="ppt-download-info">
                              <Presentation size={16} className="ppt-icon" />
                              <span className="ppt-text">PPT Report Generated</span>
                            </div>
                            <button 
                              type="button"
                              className="ppt-download-button"
                              onClick={() => {
                                handlePptDownload(pptLink.url, pptLink.filename);
                              }}
                            >
                              Download {pptLink.filename}
                            </button>
                          </div>
                        );
                      })()}

                      {/* Display PDF export button when Data Reports is selected and streaming is complete */}
                      {msg.selected_option === 'DataReports' && !(conversation && conversation.isStreaming) && (
                        <div className="doc-download-section">
                          <div className="doc-download-info">
                            <FileText size={16} className="doc-icon" />
                            <span className="doc-text">PDF Export Available</span>
                          </div>
                          <button 
                            className="doc-download-button"
                            onClick={() => {
                              handlePdfExport(msg);
                            }}
                          >
                            Download PDF
                          </button>
                        </div>
                      )}

                      {/* Display PPT export button when PPT is selected */}
                      {msg.selected_option === 'PPT' && (
                        <div className="ppt-download-section">
                          <div className="ppt-download-info">
                            <Presentation size={16} className="ppt-icon" />
                            <span className="ppt-text">PPT Export Available</span>
                          </div>
                          <button 
                            className="ppt-download-button"
                            onClick={() => {
                              handlePptExport(msg);
                            }}
                          >
                            Generate PPT
                          </button>
                        </div>
                      )}
                      
                      {/* Display chart if available */}
                      {msg.has_chart && msg.chart_spec && msg.chart_data && (
                        <div className="chart-section">
                          <ChartRenderer 
                            spec={msg.chart_spec}
                            data={msg.chart_data}
                            title={msg.chart_spec.title}
                          />
                        </div>
                      )}
                      
                      {/* Display chart error if any */}
                      {msg.chart_error && (
                        <div className="chart-error-section">
                          <div className="chart-error-info">
                            <BarChart3 size={16} className="chart-error-icon" />
                            <span className="chart-error-text">Chart Generation Error: {msg.chart_error}</span>
                          </div>
                        </div>
                      )}

                      {/* Copy button for assistant messages */}
                      {msg.type === 'assistant' && msg.content && msg.content.trim() !== '' && (
                        <div className="copy-button-section">
                          <button 
                            className="copy-button"
                            onClick={(e) => handleCopyMessage(msg.content, e)}
                            title="Copy response"
                          >
                            <Copy size={14} />
                            <span className="copy-button-text">Copy</span>
                          </button>
                        </div>
                      )}
                    </>
                  )
                }
                </div>
              </div>
            ))}
          </>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* 搴曢儴杈撳叆妗?- 鍙湪鏈夋秷鎭椂鏄剧ず */}
      {messages.length > 0 && (
        <div className="input-area">
          <form onSubmit={handleSubmit} className="input-container">
            {/* Option buttons above input */}
            {renderOptionButtons()}
            <div className="input-wrapper">
              <textarea
                ref={textareaRef}
                value={message}
                onChange={(e) => {
                  setMessage(e.target.value);
                  adjustTextareaHeight();
                }}
                onKeyPress={handleKeyPress}
                placeholder="Ask a question about your enterprise data..."
                className="message-input"
                disabled={loading}
                rows={1}
              />
              <button
                type="submit"
                className="send-button"
                disabled={!message.trim() || loading}
              >
                <Send size={16} />
              </button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
};

export default ChatInterface;

