import axios from 'axios';

// Prefer relative paths so CRA proxy handles routing in dev, avoiding cross-origin abort logs
export const API_BASE_URL = process.env.REACT_APP_API_URL || '';

const api = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Helper to build absolute URLs for SSE in production
// In dev (CRA), keep relative paths to leverage proxy
const buildStreamUrl = (pathWithQuery) => {
  if (API_BASE_URL) {
    return `${API_BASE_URL}${pathWithQuery.startsWith('/') ? '' : '/'}${pathWithQuery}`;
  }
  return pathWithQuery;
};

// Add request interceptor for debugging
api.interceptors.request.use(
  (config) => {
    console.log('API Request:', config.method?.toUpperCase(), config.url, config.data);
    return config;
  },
  (error) => {
    console.error('API Request Error:', error);
    return Promise.reject(error);
  }
);

// Add response interceptor for debugging
api.interceptors.response.use(
  (response) => {
    console.log('API Response:', response.status, response.data);
    return response;
  },
  (error) => {
    const msg = String(error?.message || '');
    const code = error?.code || '';
    // Do not log canceled/aborted requests to avoid noisy console errors
    if (code === 'ERR_CANCELED' || msg.includes('ERR_ABORTED')) {
      return Promise.reject(error);
    }
    console.error('API Response Error:', error.response?.status, error.response?.data);
    return Promise.reject(error);
  }
);

export const getConversations = async (signal) => {
  try {
    const response = await api.get('/api/conversations', { signal });
    return response.data;
  } catch (error) {
    const msg = String(error?.message || '');
    const code = error?.code || '';
    if (code === 'ERR_CANCELED' || msg.includes('ERR_ABORTED')) {
      // Swallow aborted requests quietly
      return [];
    }
    console.error('Failed to fetch conversations:', error);
    throw error;
  }
};

