// SSE streaming ask (Server-Sent Events)
export const askQuestionStream = (question) => {
  try {
    // Use absolute base in production to reach Flask API directly
    const url = buildStreamUrl(`/api/ask/stream?question=${encodeURIComponent(question)}`);
    const es = new EventSource(url);
    return es;
  } catch (error) {
    console.error('Failed to start streaming for question:', error);
    throw error;
  }
};

