export const exportToDoc = async (sessionId) => {
  try {
    const response = await api.post('/api/export/doc', {
      session_id: sessionId
    }, {
      responseType: 'blob' // Important for file download
    });
    
    // Create blob link to download
    const url = window.URL.createObjectURL(new Blob([response.data]));
    const link = document.createElement('a');
    link.href = url;
    
    // Extract filename from response headers or use default
    const contentDisposition = response.headers['content-disposition'];
    let filename = 'coffee_analysis_report.docx';
    if (contentDisposition) {
      const filenameMatch = contentDisposition.match(/filename="(.+)"/);
      if (filenameMatch) {
        filename = filenameMatch[1];
      }
    }
    
    link.setAttribute('download', filename);
    document.body.appendChild(link);
    link.click();
    link.remove();
    window.URL.revokeObjectURL(url);
    
    return { success: true, filename };
  } catch (error) {
    console.error('Failed to export to DOC:', error);
    throw error;
  }
};

export const exportToPdf = async (sessionId) => {
  try {
    // First, trigger server-side PDF export
    const resp = await api.post('/api/export', {
      session_id: sessionId,
      format: 'pdf'
    });
    const data = resp.data || {};

    // Expect a file path like 'exports/analysis_report_XXXXXXXX.pdf'
    const filePath = data.file_path;
    if (!filePath) {
      throw new Error('PDF export failed: no file_path returned');
    }

    // Derive filename from path and download via /api/download/<filename>
    const filename = filePath.split(/[/\\]/).pop();
    const downloadUrl = `/api/download/${filename}`;

    // Fetch as blob and prompt Save As
    const dlResp = await api.get(downloadUrl, { responseType: 'blob' });
    const blob = new Blob([dlResp.data], { type: 'application/pdf' });

    const objectUrl = window.URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = objectUrl;
    link.download = filename || 'analysis_report.pdf';
    document.body.appendChild(link);
    link.click();
    link.remove();
    window.URL.revokeObjectURL(objectUrl);

    return { success: true, filename };
  } catch (error) {
    console.error('Failed to export to PDF:', error);
    throw error;
  }
};

