import React from 'react';
import { VegaEmbed } from 'react-vega';

const ChartRenderer = ({ spec, data, title }) => {
  if (!spec || !data) {
    return <div className="chart-placeholder">No chart data available</div>;
  }

  // Merge spec with data and configure for 2K resolution
  const chartSpec = {
    ...spec,
    data: { values: data },
    title: title || spec.title,
    width: 'container',
    height: 600, // Reasonable height for display
    autosize: {
      type: 'fit',
      contains: 'padding'
    },
    config: {
      ...spec.config,
      view: {
        ...spec.config?.view,
        continuousWidth: 1920,
        continuousHeight: 1080,
        stroke: 'transparent'
      },
      // High-quality rendering settings
      axis: {
        ...spec.config?.axis,
        labelFontSize: 14,
        titleFontSize: 16,
        tickSize: 8
      },
      legend: {
        ...spec.config?.legend,
        labelFontSize: 14,
        titleFontSize: 16
      },
      title: {
        ...spec.config?.title,
        fontSize: 20,
        fontWeight: 'bold'
      }
    }
  };

  return (
    <div className="chart-container" style={{ width: '100%', marginBottom: '20px' }}>
      <VegaEmbed 
        spec={chartSpec} 
        actions={{ export: true, source: false, editor: false }}
        options={{
          renderer: 'svg',
          scaleFactor: 2
        }}
        style={{ width: '100%' }}
      />
    </div>
  );
};

export default ChartRenderer;