import React, { useState, useEffect, useRef } from 'react';
import Sidebar from './components/Sidebar';
import NarrowSidebar from './components/NarrowSidebar';
import ChatInterface from './components/ChatInterface';
import { getConversations, getConversationDetails, askQuestion, askFollowup, deleteConversation, askQuestionStream, askFollowupStream } from './services/api';
import './App.css';

function App() {
  const [conversations, setConversations] = useState([]);
  const [currentConversation, setCurrentConversation] = useState(null);
  const [loading, setLoading] = useState(false);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [sidebarWidth, setSidebarWidth] = useState(260);
  const conversationsAbortRef = useRef(null);

  useEffect(() => {
    const ctrl = new AbortController();
    conversationsAbortRef.current = ctrl;
    loadConversations(ctrl.signal);
    
    // Clean up any orphaned temporary conversations on page load
    const cleanupTempConversations = () => {
      setConversations(prevConversations => 
        prevConversations.filter(conv => !conv.isTemporary)
      );
      setCurrentConversation(prev => 
        prev && prev.isTemporary ? null : prev
      );
      
      // Clear any temporary conversation data from localStorage
      try {
        const keys = Object.keys(localStorage);
        keys.forEach(key => {
          if (key.startsWith('temp_conversation_') || key.startsWith('temp-conversation-')) {
            localStorage.removeItem(key);
          }
        });
      } catch (error) {
        console.warn('Failed to clean localStorage:', error);
      }
    };
    
    // Handle page visibility changes to prevent duplicate conversations
    const handleVisibilityChange = () => {
      if (document.visibilityState === 'visible') {
        // When page becomes visible, clean up any temporary conversations
        cleanupTempConversations();
      }
    };
    
    // Clean up on initial load
    cleanupTempConversations();
    
    // Add event listener for page visibility changes
    document.addEventListener('visibilitychange', handleVisibilityChange);
    
    return () => {
      try { conversationsAbortRef.current?.abort(); } catch (_) {}
      conversationsAbortRef.current = null;
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, []);

  const loadConversations = async (signal) => {
    try {
      const data = await getConversations(signal);
      setConversations(data);
    } catch (error) {
      // Ignore aborted/canceled fetches which can occur during rapid updates
      const msg = String(error?.message || '');
      const code = error?.code || '';
      if (code === 'ERR_CANCELED' || msg.includes('ERR_ABORTED')) {
        return;
      }
      console.error('Failed to load conversations:', error);
    }
  };

  const handleNewConversation = () => {
    // Check if there's already a temporary conversation
    const existingTempConversation = conversations.find(conv => conv.isTemporary);
    
    if (existingTempConversation) {
      // If there's already a temporary conversation, just select it
      setCurrentConversation(existingTempConversation);
      return;
    }
    
    // Create a temporary conversation that appears immediately in the sidebar
    const tempConversation = {
      session_id: `temp_${Date.now()}`, // Temporary ID
      question_summary: "New Chat",
      created_at: new Date().toISOString(),
      language: "chinese",
      followup_count: 0,
      isTemporary: true, // Flag to identify temporary conversations
      original_question: null,
      original_sql: null,
      original_data: null,
      original_columns: null,
      original_analysis: null,
      conversation_history: []
    };
    
    // Add the temporary conversation to the beginning of the conversations list
    setConversations(prevConversations => [tempConversation, ...prevConversations]);
    
    // Set it as the current conversation
    setCurrentConversation(tempConversation);
  };

  const handleSelectConversation = async (conversation) => {
    try {
      setLoading(true);
      
      // If it's a temporary conversation, just set it directly
      if (conversation.isTemporary) {
        setCurrentConversation(conversation);
        return;
      }
      
      // Validate conversation ID format to prevent invalid API calls
      if (!conversation.session_id || conversation.session_id.startsWith('temp_') || conversation.session_id.startsWith('temp-')) {
        console.warn('Invalid conversation ID detected, skipping API call:', conversation.session_id);
        setCurrentConversation(null);
        return;
      }
      
      const conversationDetails = await getConversationDetails(conversation.session_id);
      setCurrentConversation(conversationDetails);
    } catch (error) {
      console.error('Failed to load conversation details:', error);
      // For 404 errors or invalid conversations, clear the selection
      if (error.status === 404 || error.message?.includes('404')) {
        setCurrentConversation(null);
        // Remove the invalid conversation from the list
        setConversations(prevConversations => 
          prevConversations.filter(conv => conv.session_id !== conversation.session_id)
        );
      } else {
        // For other errors, fallback to basic conversation data
        setCurrentConversation(conversation);
      }
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteConversation = async (sessionId) => {
    try {
      // Check if it's a temporary conversation
      const conversationToDelete = conversations.find(conv => conv.session_id === sessionId);
      
      if (conversationToDelete && conversationToDelete.isTemporary) {
        // For temporary conversations, just remove from local state
        setConversations(prevConversations => 
          prevConversations.filter(conv => conv.session_id !== sessionId)
        );
        
        // If the deleted conversation is currently selected, clear it
        if (currentConversation && currentConversation.session_id === sessionId) {
          setCurrentConversation(null);
        }
      } else {
        // For real conversations, delete from server
        await deleteConversation(sessionId);
        
        // If the deleted conversation is currently selected, clear it
        if (currentConversation && currentConversation.session_id === sessionId) {
          setCurrentConversation(null);
        }
        
        // Save temporary conversations before reloading
        const tempConversations = conversations.filter(conv => conv.isTemporary);
        
        // Reload conversations list
        await loadConversations();
        
        // Restore temporary conversations after reloading
        if (tempConversations.length > 0) {
          setConversations(prevConversations => [...tempConversations, ...prevConversations]);
        }
      }
    } catch (error) {
      console.error('Failed to delete conversation:', error);
      alert('Failed to delete conversation. Please try again.');
    }
  };

  const handleSendMessage = async (message, isFollowup = false) => {
    // Prevent duplicate message sending
    if (loading) {
      console.warn('Message already being sent, ignoring duplicate request');
      return;
    }
    
    setLoading(true);
    const thinkingStartTime = Date.now(); // Record thinking start time
    
    try {
      let response;
      
      // Check if current conversation is temporary
      if (currentConversation && currentConversation.isTemporary) {
        // Create a new conversation (not followup)
        isFollowup = false;
      }
      
      if (isFollowup && currentConversation && !currentConversation.isTemporary) {
        // Follow-up: start SSE streaming and apply fade-in
        const tempConversation = {
          ...currentConversation,
          conversation_history: [
            ...(currentConversation.conversation_history || []),
            {
              type: 'followup',
              question: message,
              timestamp: new Date().toISOString(),
              analysis: '',
              sql_query: null,
              query_result: null,
              columns: null,
              isLoading: false
            }
          ],
          isStreaming: true
        };
        setCurrentConversation(tempConversation);

        const es = askFollowupStream(currentConversation.session_id, message);
        let closedByDone = false; // Prevent false error state when we intentionally close

        es.addEventListener('start', (ev) => {
          try {
            const payload = JSON.parse(ev.data || '{}');
            setCurrentConversation(prev => {
              const ch = [...(prev.conversation_history || [])];
              const lastIdx = ch.length - 1;
              if (lastIdx >= 0) {
                ch[lastIdx] = {
                  ...ch[lastIdx],
                  selected_option: payload.selected_option || ch[lastIdx]?.selected_option
                };
              }
              return { ...prev, conversation_history: ch, isStreaming: true };
            });
          } catch (_) {}
        });

        es.addEventListener('analysis_token', (ev) => {
          try {
            const payload = JSON.parse(ev.data || '{}');
            const token = payload.text || '';
            const thinkingTime = ((Date.now() - thinkingStartTime) / 1000).toFixed(1);
            setCurrentConversation(prev => {
              const ch = [...(prev.conversation_history || [])];
              const lastIdx = ch.length - 1;
              if (lastIdx >= 0) {
                const last = ch[lastIdx] || {};
                ch[lastIdx] = { 
                  ...last, 
                  analysis: (last.analysis || '') + token, 
                  isLoading: false,
                  thinkingTime: !last.analysis ? thinkingTime : last.thinkingTime // Only set on first token
                };
              }
              return { ...prev, conversation_history: ch };
            });
          } catch (_) {}
        });

        es.addEventListener('analysis_final', (ev) => {
          try {
            const payload = JSON.parse(ev.data || '{}');
            const text = payload.text || '';
            setCurrentConversation(prev => {
              const ch = [...(prev.conversation_history || [])];
              const lastIdx = ch.length - 1;
              if (lastIdx >= 0) {
                const last = ch[lastIdx] || {};
                ch[lastIdx] = { ...last, analysis: text, isLoading: false };
              }
              return { ...prev, conversation_history: ch, isStreaming: false };
            });
          } catch (_) {}
        });

        es.addEventListener('done', async (ev) => {
          try {
            const payload = JSON.parse(ev.data || '{}');
            closedByDone = true;
            es.close();
            if (payload.error) {
              setCurrentConversation(prev => ({
                ...prev,
                isStreaming: false,
                isError: true,
                errorMessage: payload.error
              }));
              setLoading(false);
              return;
            }

            setCurrentConversation(prev => {
              const ch = [...(prev.conversation_history || [])];
              const lastIdx = ch.length - 1;
              if (lastIdx >= 0) {
                const last = ch[lastIdx] || {};
                ch[lastIdx] = {
                  ...last,
                  doc_file_url: payload.doc_file_url || last.doc_file_url,
                  doc_filename: payload.doc_filename || last.doc_filename,
                  auto_doc_generated: payload.doc_file_url ? true : last.auto_doc_generated,
                  // Add Excel data handling for followup questions
                  excel_file_url: payload.excel_file_url || last.excel_file_url,
                  excel_filename: payload.excel_filename || last.excel_filename,
                  auto_excel_generated: payload.excel_file_url ? true : last.auto_excel_generated,
                  // Add chart data handling for followup questions - only use new chart data
                  has_chart: payload.has_chart || false,
                  chart_spec: payload.chart_spec || null,
                  chart_data: payload.chart_data || null,
                  chart_type: payload.chart_type || null,
                  chart_error: payload.chart_error || null
                };
              }
              return {
                ...prev,
                conversation_history: ch,
                isLoading: false,
                doc_file_url: payload.doc_file_url || prev.doc_file_url,
                doc_filename: payload.doc_filename || prev.doc_filename,
                auto_doc_generated: payload.doc_file_url ? true : prev.auto_doc_generated,
                // Add Excel data handling for followup questions
                excel_file_url: payload.excel_file_url || prev.excel_file_url,
                excel_filename: payload.excel_filename || prev.excel_filename,
                auto_excel_generated: payload.excel_file_url ? true : prev.auto_excel_generated,
                // Add chart data handling for followup questions - only use new chart data
                has_chart: payload.has_chart || false,
                chart_spec: payload.chart_spec || null,
                chart_data: payload.chart_data || null,
                chart_type: payload.chart_type || null,
                chart_error: payload.chart_error || null
              };
            });

            await loadConversations();
          } catch (err) {
            setCurrentConversation(prev => ({
              ...prev,
              isStreaming: false,
              isError: true,
              errorMessage: 'Streaming completed with errors.'
            }));
          } finally {
            setLoading(false);
          }
        });

        es.onerror = (err) => {
          // Ignore the error if we purposely closed after receiving 'done'
          if (!closedByDone) {
            try { es.close(); } catch (_) {}
            setCurrentConversation(prev => ({
              ...prev,
              isStreaming: false,
              isError: true,
              errorMessage: 'Streaming connection error.'
            }));
          }
          setLoading(false);
        };
      } else {
        // New conversation: start SSE streaming
        const tempConversation = {
          session_id: `temp_${Date.now()}`,
          original_question: message,
          original_analysis: '',
          original_sql: null,
          original_data: null,
          original_columns: null,
          created_at: new Date().toISOString(),
          conversation_history: [],
          isLoading: false,
          isStreaming: true
        };
        setCurrentConversation(tempConversation);

        // Update conversations list
        if (currentConversation && currentConversation.isTemporary) {
          setConversations(prevConversations => 
            prevConversations.map(conv => 
              conv.session_id === currentConversation.session_id ? tempConversation : conv
            )
          );
        } else {
          setConversations(prevConversations => [tempConversation, ...prevConversations]);
        }

        const es = askQuestionStream(message);
        let closedByDone = false; // Prevent false error state when we intentionally close

        es.addEventListener('start', (ev) => {
          try {
            const payload = JSON.parse(ev.data || '{}');
            setCurrentConversation(prev => ({
              ...prev,
              selected_option: payload.selected_option || prev?.selected_option
            }));
          } catch (_) {}
        });

        es.addEventListener('analysis_token', (ev) => {
          try {
            const payload = JSON.parse(ev.data || '{}');
            const token = payload.text || '';
            const thinkingTime = ((Date.now() - thinkingStartTime) / 1000).toFixed(1);
            setCurrentConversation(prev => ({
              ...prev,
              original_analysis: (prev.original_analysis || '') + token,
              thinkingTime: !prev.original_analysis ? thinkingTime : prev.thinkingTime // Only set on first token
            }));
          } catch (_) {}
        });

        es.addEventListener('analysis_final', (ev) => {
          try {
            const payload = JSON.parse(ev.data || '{}');
            const text = payload.text || '';
            // Do not dump full content abruptly; ensure smooth continuation
            setCurrentConversation(prev => ({
              ...prev,
              original_analysis: text,
              isStreaming: false
            }));
          } catch (_) {}
        });

        es.addEventListener('done', async (ev) => {
          try {
            const payload = JSON.parse(ev.data || '{}');
            closedByDone = true;
            es.close();
            if (payload.error) {
              setCurrentConversation(prev => ({
                ...prev,
                isStreaming: false,
                isError: true,
                errorMessage: payload.error
              }));
              setLoading(false);
              return;
            }

            const sessionId = payload.session_id;
            setCurrentConversation(prev => ({
              ...prev,
              session_id: sessionId,
              isLoading: false,
              original_sql: Array.isArray(payload.sql_list) ? payload.sql_list.join('\n\n') : prev.original_sql,
              doc_file_url: payload.doc_file_url || prev.doc_file_url,
              doc_filename: payload.doc_filename || prev.doc_filename,
              auto_doc_generated: !!payload.doc_file_url || prev.auto_doc_generated,
              excel_file_url: payload.excel_file_url || prev.excel_file_url,
              excel_filename: payload.excel_filename || prev.excel_filename,
              auto_excel_generated: !!payload.excel_file_url || prev.auto_excel_generated,
              // Include chart fields for new conversations so charts render immediately
              has_chart: payload.has_chart ?? prev.has_chart,
              chart_spec: payload.chart_spec ?? prev.chart_spec,
              chart_data: payload.chart_data ?? prev.chart_data,
              chart_type: payload.chart_type ?? prev.chart_type,
              chart_error: payload.chart_error ?? prev.chart_error
            }));

            // Save other temporary conversations before reloading
            const otherTempConversations = conversations.filter(conv => 
              conv.isTemporary && conv.session_id !== tempConversation.session_id
            );
            
            await loadConversations();
            
            // Restore other temporary conversations after reloading
            if (otherTempConversations.length > 0) {
              setConversations(prevConversations => [...otherTempConversations, ...prevConversations]);
            }
          } catch (err) {
            setCurrentConversation(prev => ({
              ...prev,
              isStreaming: false,
              isError: true,
              errorMessage: 'Streaming completed with errors.'
            }));
          } finally {
            setLoading(false);
          }
        });

        es.onerror = (err) => {
          // Ignore the error if we purposely closed after receiving 'done'
          if (!closedByDone) {
            try { es.close(); } catch (_) {}
            setCurrentConversation(prev => ({
              ...prev,
              isStreaming: false,
              isError: true,
              errorMessage: 'Streaming connection error.'
            }));
          }
          setLoading(false);
        };
      }
      
      return response;
    } catch (error) {
      console.error('Failed to send message:', error);
      
      // Update conversation to show error state
      if (currentConversation) {
        const errorConversation = {
          ...currentConversation,
          isError: true,
          errorMessage: 'Failed to send message. Please try again.'
        };
        setCurrentConversation(errorConversation);
      }
      
      throw error;
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="app">
      {sidebarCollapsed && (
        <NarrowSidebar
          onToggleExpand={() => setSidebarCollapsed(false)}
          onNewConversation={handleNewConversation}
        />
      )}
      <Sidebar
        conversations={conversations}
        currentConversation={currentConversation}
        onNewConversation={handleNewConversation}
        onSelectConversation={handleSelectConversation}
        onDeleteConversation={handleDeleteConversation}
        collapsed={sidebarCollapsed}
        onToggleCollapse={() => setSidebarCollapsed(!sidebarCollapsed)}
        width={sidebarCollapsed ? 0 : sidebarWidth}
        onResize={setSidebarWidth}
      />
      <ChatInterface
        conversation={currentConversation}
        onSendMessage={handleSendMessage}
        loading={loading}
        sidebarCollapsed={sidebarCollapsed}
        narrowSidebarVisible={sidebarCollapsed}
      />
    </div>
  );
}

export default App;